// SPDX-License-Identifier: AGPL-3.0-only
//! Keys and their derivations (`backup-format.md` section 3).
//!
//! All keys are 256 bits. [`RepoKey`] is generated by the primary once per
//! repository; [`SourceKeys`] are derived from it per source and are the only
//! key material a node holds. `BLAKE3` in key-derivation mode with the context
//! strings below, which are fixed for format version 1, produces all of them.

use std::fmt;

use blake3::derive_key;
use zeroize::Zeroize;

use crate::util;

/// Context of the per-source key, fixed for format version 1 (section 3).
const SOURCE_KEY_CONTEXT: &str = "quoro backup source v1";
/// Context of the chunk id key, fixed for format version 1 (section 3).
const ID_KEY_CONTEXT: &str = "quoro backup chunk id v1";
/// Context of the chunk data key, fixed for format version 1 (section 3).
const DATA_KEY_CONTEXT: &str = "quoro backup chunk data v1";

/// A 256-bit secret. It is zeroed when dropped and never printed.
///
/// [`fmt::Debug`] prints `Key([redacted])`, so a key cannot leak through a log
/// line or a panic message.
#[derive(Clone)]
pub struct Key([u8; 32]);

impl Key {
    /// The key from its 32 bytes, the form a node receives in a job.
    #[must_use]
    pub fn from_bytes(bytes: [u8; 32]) -> Self {
        Self(bytes)
    }

    /// The raw bytes, for the derivations and the AEAD.
    #[must_use]
    pub fn as_bytes(&self) -> &[u8; 32] {
        &self.0
    }

    /// 32 fresh random bytes from the operating-system generator.
    ///
    /// # Panics
    ///
    /// Panics if the operating system's random generator fails.
    #[must_use]
    pub fn generate() -> Self {
        Self(util::random_bytes())
    }
}

impl Drop for Key {
    fn drop(&mut self) {
        self.0.zeroize();
    }
}

impl fmt::Debug for Key {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("Key([redacted])")
    }
}

impl PartialEq for Key {
    fn eq(&self, other: &Self) -> bool {
        self.0 == other.0
    }
}

impl Eq for Key {}

/// The repository key: 32 random bytes generated by the primary when the
/// repository is created (section 3).
///
/// It never reaches a node. A node gets the [`SourceKeys`] of the one source it
/// was given a job for.
#[derive(Clone, Debug)]
pub struct RepoKey(Key);

impl RepoKey {
    /// 32 fresh random bytes from the operating-system generator.
    ///
    /// # Panics
    ///
    /// Panics if the operating system's random generator fails.
    #[must_use]
    pub fn generate() -> Self {
        Self(Key::generate())
    }

    /// The repo key from its 32 bytes, as `backup_repositories.repo_key_enc`
    /// stores it after unwrapping.
    #[must_use]
    pub fn from_bytes(bytes: [u8; 32]) -> Self {
        Self(Key::from_bytes(bytes))
    }

    /// The raw bytes, for wrapping under the recovery key.
    #[must_use]
    pub fn as_bytes(&self) -> &[u8; 32] {
        self.0.as_bytes()
    }

    /// The two keys of `source_id` (section 3).
    #[must_use]
    pub fn source_keys(&self, source_id: &str) -> SourceKeys {
        let mut material = Vec::with_capacity(32 + source_id.len());
        material.extend_from_slice(self.0.as_bytes());
        material.extend_from_slice(source_id.as_bytes());
        let mut source_key = derive_key(SOURCE_KEY_CONTEXT, &material);
        material.zeroize();
        let id_key = Key::from_bytes(derive_key(ID_KEY_CONTEXT, &source_key));
        let data_key = Key::from_bytes(derive_key(DATA_KEY_CONTEXT, &source_key));
        source_key.zeroize();
        SourceKeys { id_key, data_key }
    }
}

/// The keys of one source: the chunk id key and the chunk data key.
///
/// A job carries exactly these two (section 3, `node-agent-protocol.md` section
/// 5.11). Dedup is per source, so two apps with identical data store it twice.
#[derive(Clone, Debug)]
pub struct SourceKeys {
    /// Keyed BLAKE3 over the plaintext names a chunk.
    pub id_key: Key,
    /// XChaCha20-Poly1305 key that encrypts a chunk's compressed plaintext.
    pub data_key: Key,
}

#[cfg(test)]
mod tests {
    use super::*;

    /// One pinned vector: if a context string or the derivation order changes,
    /// this test fails. Computed once for format version 1 (section 3).
    const PINNED_SOURCE_KEYS: (&str, &str) = (
        "4a2f8a5bb09f096748d68572b728c27666c1e6f6207d289a048a31cb2ccae795",
        "f6c150f77b51541a6a78f4bffc1456bc938f24a5d148a5075ec30aff6254ed63",
    );

    fn pinned_repo_key() -> RepoKey {
        RepoKey::from_bytes([0x42; 32])
    }

    #[test]
    fn derivations_are_pinned_to_format_version_1() {
        let keys = pinned_repo_key().source_keys("app_01JC9Z7B3N5Q7S9Z1W3Y5A7C9E");
        assert_eq!(
            (
                util::to_hex(keys.id_key.as_bytes()),
                util::to_hex(keys.data_key.as_bytes())
            ),
            (
                PINNED_SOURCE_KEYS.0.to_owned(),
                PINNED_SOURCE_KEYS.1.to_owned()
            )
        );
    }

    #[test]
    fn different_sources_get_different_keys() {
        let repo = pinned_repo_key();
        let a = repo.source_keys("app_one");
        let b = repo.source_keys("app_two");
        assert_ne!(a.id_key, b.id_key);
        assert_ne!(a.data_key, b.data_key);
        assert_ne!(a.id_key, a.data_key);
        let again = repo.source_keys("app_one");
        assert_eq!(a.id_key, again.id_key);
        assert_eq!(a.data_key, again.data_key);
    }

    #[test]
    fn debug_never_prints_a_key() {
        assert_eq!(format!("{:?}", Key::generate()), "Key([redacted])");
    }
}
